#!/bin/bash
# What Does GRUB Boot? sysroot/boot/grub/grub.cfg in the style of Ubuntu's
# generated file: three kernels, an "Advanced options" submenu and
# set default="1>2", which points INSIDE the submenu (the 3rd entry, counting
# from 0). Traps: counting from 1, the submenu counting as an entry, and the
# first menuentry in the file (the newest kernel) not being the default.
SANDBOX="$1"
cd "$SANDBOX" || exit 1
mkdir -p sysroot/boot/grub .lm-state

entry() {  # entry TITLE VERSION [recovery]
  local title="$1" ver="$2" rec="$3" id="$4" indent="$5" extra=""
  [ -n "$rec" ] && extra=" recovery nomodeset dis_ucode_ldr"
  [ -z "$rec" ] && extra=" quiet splash \$vt_handoff"
  cat <<EOT
${indent}menuentry '$title' --class ubuntu --class gnu-linux --class gnu --class os \$menuentry_id_option '$id' {
${indent}	recordfail
${indent}	load_video
${indent}	gfxmode \$linux_gfx_mode
${indent}	insmod gzio
${indent}	insmod part_gpt
${indent}	insmod ext2
${indent}	search --no-floppy --fs-uuid --set=root 5b0e2c1a-93d4-4f0e-8a61-0c7d4be21f35
${indent}	echo	'Loading Linux $ver ...'
${indent}	linux	/boot/vmlinuz-$ver root=UUID=5b0e2c1a-93d4-4f0e-8a61-0c7d4be21f35 ro$extra
${indent}	echo	'Loading initial ramdisk ...'
${indent}	initrd	/boot/initrd.img-$ver
${indent}}
EOT
}

{
cat <<'EOT'
#
# DO NOT EDIT THIS FILE
#
# It is automatically generated by grub-mkconfig using templates
# from /etc/grub.d and settings from /etc/default/grub
#

### BEGIN /etc/grub.d/00_header ###
if [ -s $prefix/grubenv ]; then
  set have_grubenv=true
  load_env
fi
# set default="0"    (the stock value, replaced by the pinned entry below)
set default="1>2"
if [ x"${feature_menuentry_id}" = xy ]; then
  menuentry_id_option="--id"
else
  menuentry_id_option=""
fi
export menuentry_id_option
set timeout=5
### END /etc/grub.d/00_header ###

### BEGIN /etc/grub.d/10_linux ###
EOT
entry "Ubuntu" 6.8.0-45-generic "" gnulinux-simple-5b0e2c1a-93d4-4f0e-8a61-0c7d4be21f35 ""
echo "submenu 'Advanced options for Ubuntu' \$menuentry_id_option 'gnulinux-advanced-5b0e2c1a-93d4-4f0e-8a61-0c7d4be21f35' {"
entry "Ubuntu, with Linux 6.8.0-45-generic" 6.8.0-45-generic "" gnulinux-6.8.0-45-generic-advanced-5b0e2c1a "	"
entry "Ubuntu, with Linux 6.8.0-45-generic (recovery mode)" 6.8.0-45-generic r gnulinux-6.8.0-45-generic-recovery-5b0e2c1a "	"
entry "Ubuntu, with Linux 6.8.0-31-generic" 6.8.0-31-generic "" gnulinux-6.8.0-31-generic-advanced-5b0e2c1a "	"
entry "Ubuntu, with Linux 6.8.0-31-generic (recovery mode)" 6.8.0-31-generic r gnulinux-6.8.0-31-generic-recovery-5b0e2c1a "	"
entry "Ubuntu, with Linux 5.15.0-118-generic" 5.15.0-118-generic "" gnulinux-5.15.0-118-generic-advanced-5b0e2c1a "	"
entry "Ubuntu, with Linux 5.15.0-118-generic (recovery mode)" 5.15.0-118-generic r gnulinux-5.15.0-118-generic-recovery-5b0e2c1a "	"
echo "}"
cat <<'EOT'
### END /etc/grub.d/10_linux ###

### BEGIN /etc/grub.d/30_uefi-firmware ###
menuentry 'UEFI Firmware Settings' $menuentry_id_option 'uefi-firmware' {
	fwsetup
}
### END /etc/grub.d/30_uefi-firmware ###
EOT
} > sysroot/boot/grub/grub.cfg

cksum sysroot/boot/grub/grub.cfg > .lm-state/cfg
printf '%s\n' "Ubuntu, with Linux 6.8.0-31-generic" > .lm-state/title
printf '%s\n' "6.8.0-31-generic" > .lm-state/kernel
